        return 0;
    }

    static TreeNode buildTree(List<String> tokens) {
        if (tokens.isEmpty() || tokens.get(0).equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(tokens.get(0)));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tokens.size()) {
            TreeNode node = q.poll();
            if (i < tokens.size()) {
                if (!tokens.get(i).equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(tokens.get(i)));
                    q.add(node.left);
                }
                i++;
            }
            if (i < tokens.size()) {
                if (!tokens.get(i).equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(tokens.get(i)));
                    q.add(node.right);
                }
                i++;
            }
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        List<String> tokens = new ArrayList<>();
        while (st.hasMoreTokens()) tokens.add(st.nextToken());
        System.out.println(widthOfBinaryTree(buildTree(tokens)));
    }
}
